        cr.curveTo(cx + a * 0.95, cy + b * 0.8, cx + a * 0.5, cy + b, cx, cy + b);
        cr.curveTo(cx - a * 0.5, cy + b, cx - a * 0.95, cy + b * 0.8, cx - a, cy + b * 0.15);
